import os
for r,d,f in os.walk('studies'):
    for x in f: print(os.path.join(r,x), os.path.getsize(os.path.join(r,x)))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith(('!Series_title','!Series_summary','!Series_overall','!Sample_title','!Sample_characteristics','!Sample_source','!Sample_platform','!Sample_treatment','!Sample_data_processing','!Series_platform','!Sample_label','!Sample_molecule')):
            print(l[:700].rstrip())

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    print('=====',f)
    rows=[]
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith(('!Series_summary','!Series_overall','!Series_title')): print(l[:1500].rstrip())
        if l.startswith(('!Sample_title','!Sample_characteristics','!Sample_source','!Sample_data_processing','!Sample_treatment','!Sample_growth','!Sample_extract')):
            rows.append(l.rstrip().split('\t'))
    import collections
    for r in rows:
        vals=[v.strip('"') for v in r[1:]]
        if 'title' in r[0] or 'characteristics' in r[0] or 'source' in r[0]:
            print(r[0], collections.Counter(vals).most_common(40) if 'title' not in r[0] else vals)
        else:
            print(r[0], set(v[:600] for v in vals))

